#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char* replace(char* s, char* old, char* new) {
    char* sub = strstr(s, old);

    if(sub == NULL) {
        return s;
    }

    char* res = (char*) calloc(100, sizeof(char));

    while (sub != NULL) {
        sub[0] = '\0';
        strcat(res, s);
        strcat(res, new);

        s = sub + strlen(old);
        sub = strstr(s, old);
    }

    strcat(res, s);

    return res;
}

int main() {
    char* s = (char*) calloc(100, sizeof(char));
    gets(s);

    for (int i = 26; i >= 1; i--) {
        char key[4];
        sprintf(key, "%d", i);

        if(i > 9) {
            strcat(key, "*");
        }

        char val[2];
        sprintf(val, "%c", 97 + i - 1);

        s = replace(s, key, val);
    }

    puts(s);

    return 0;
}
